package com.duckblade.osrs.tfa;

import java.util.Collections;
import java.util.Map;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class ConfigMigrationService
{

	@Inject
	private ConfigManager configManager;

	void migrate()
	{
	}

	private <Source, Dest> void migrate(String oldKey, String newKey, Class<Source> sourceType, Function<Source, Dest> migration)
	{
		migrateMany(oldKey, sourceType, s -> Collections.singletonMap(newKey, migration.apply(s)));
	}

	private <Source> void migrateMany(String oldKey, Class<Source> sourceType, Function<Source, Map<String, Object>> migration)
	{
		Source previousEntry = configManager.getConfiguration(TfaConfig.CONFIG_GROUP, oldKey, sourceType);
		if (previousEntry != null)
		{
			configManager.unsetConfiguration(TfaConfig.CONFIG_GROUP, oldKey);
			Map<String, Object> newEntries = migration.apply(previousEntry);
			newEntries.forEach((k, v) -> configManager.setConfiguration(TfaConfig.CONFIG_GROUP, k, v));
		}
	}

}

package com.duckblade.osrs.tfa;

import com.duckblade.osrs.tfa.features.hporbs.HpOrbMode;
import com.duckblade.osrs.tfa.features.pointstracker.PointsTrackerOverlayEnableMode;
import com.duckblade.osrs.tfa.features.updatenotifier.UpdateNotifier;
import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(TfaConfig.CONFIG_GROUP)
public interface TfaConfig extends Config
{

	String CONFIG_GROUP = "thefracturedarchive";

	// Sections

	@ConfigSection(
		name = "Miscellaneous",
		description = "Miscellaneous configurations.",
		position = 0,
		closedByDefault = false
	)
	String SECTION_MISCELLANEOUS = "sectionMiscellaneous";

	@ConfigSection(
		name = "Lobby",
		description = "Options for the raid lobby.",
		position = 1,
		closedByDefault = true
	)
	String SECTION_LOBBY = "sectionLobby";

	@ConfigSection(
		name = "Loot",
		description = "Options for the loot room.",
		position = 2,
		closedByDefault = true
	)
	String SECTION_LOOT = "sectionLoot";

	@ConfigSection(
		name = "Points Tracker",
		description = "Options for the points tracker.",
		position = 3,
		closedByDefault = true
	)
	String SECTION_POINTS_TRACKER = "pointsTracker";

	// Miscellaneous

	@ConfigItem(
		keyName = "showUpdateMessages",
		name = "Show Updates",
		description = "Opens a panel describing plugin updates after new features are added to the plugin.",
		position = 0,
		section = SECTION_MISCELLANEOUS
	)
	default boolean showUpdateMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hpOrbsMode",
		name = "HP Orbs",
		description = "Removes HP orbs from the screen or replaces them with health bars.",
		position = 2,
		section = SECTION_MISCELLANEOUS
	)
	default HpOrbMode hpOrbsMode()
	{
		return HpOrbMode.ORBS;
	}

	@ConfigItem(
		keyName = "hideFadeTransition",
		name = "Hide Fade Transition",
		description = "Hides the fade transition between loading zones.",
		position = 3,
		section = SECTION_MISCELLANEOUS
	)
	default boolean hideFadeTransition()
	{
		return false;
	}

	// Lobby

	@ConfigItem(
		keyName = "lobbyBoardFriendHighlighter",
		name = "Lobby Board Highlight",
		description = "Highlight friends' and ignores' names on the lobby party finder board.",
		section = SECTION_LOBBY,
		position = 0
	)
	default boolean lobbyBoardFriendHighlighter()
	{
		return true;
	}

	@ConfigItem(
		keyName = "lobbyLootReminder",
		name = "Loot Reminder",
		description = "Reminds you to claim your loot when in the raid lobby. You will not be able to start the raid unless you claim your loot.",
		section = SECTION_LOBBY,
		position = 1
	)
	default boolean lobbyLootReminder()
	{
		return true;
	}

	@ConfigItem(
		keyName = "lobbySpellbookWarning",
		name = "Spellbook Warning",
		description = "Shows your current spellbook on the raid entrance.",
		section = SECTION_LOBBY,
		position = 2
	)
	default boolean lobbySpellbookWarning()
	{
		return false;
	}

	// Loot

	@ConfigItem(
		keyName = "leftClickBankAll",
		name = "Bank-all Single Click",
		description = "Allows you to Bank-all loot without requiring a second click on the minimenu.",
		section = SECTION_LOOT,
		position = 0
	)
	default boolean leftClickBankAll()
	{
		return true;
	}

	@ConfigItem(
		keyName = "lootChestHighlightEnabled",
		name = "Loot Chest Highlight",
		description = "",
		position = 1,
		section = SECTION_LOOT
	)
	default boolean lootChestHighlightEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "lootChestGlowStrength",
		name = " ↳ Strength",
		description = "",
		position = 2,
		section = SECTION_LOOT
	)
	@Range(min = 1, max = 20)
	default int lootChestGlowStrength()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "lootChestGlowColourStandard",
		name = " ↳ Colour - Standard",
		description = "",
		position = 3,
		section = SECTION_LOOT
	)
	@Alpha
	default Color lootChestGlowColourStandard()
	{
		return new Color(255, 255, 255, 64);
	}

	@ConfigItem(
		keyName = "lootChestGlowColourUnique",
		name = " ↳ Colour - Unique",
		description = "",
		position = 5,
		section = SECTION_LOOT
	)
	@Alpha
	default Color lootChestGlowColourUnique()
	{
		return new Color(128, 0, 64, 128);
	}

	// points tracker

	@ConfigItem(
		keyName = "pointsTrackerOverlayEnableMode",
		name = "Enable Overlay",
		description = "Show points earned within the raid.",
		position = 0,
		section = SECTION_POINTS_TRACKER
	)
	default PointsTrackerOverlayEnableMode pointsTrackerOverlayEnableMode()
	{
		return PointsTrackerOverlayEnableMode.ALWAYS;
	}

	@ConfigItem(
		keyName = "pointsTrackerShowTeamPoints",
		name = "Show Team Points",
		description = "Show team points on the overlay.",
		position = 1,
		section = SECTION_POINTS_TRACKER
	)
	default boolean pointsTrackerShowTeamPoints()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pointsTrackerShowPersonalPoints",
		name = "Show Personal Points",
		description = "Show unique chance on the overlay.",
		position = 2,
		section = SECTION_POINTS_TRACKER
	)
	default boolean pointsTrackerShowPersonalPoints()
	{
		return false;
	}

	@ConfigItem(
		keyName = "pointsTrackerShowTeamUniqueChance",
		name = "Show Team Unique %",
		description = "Show unique chance on the overlay.",
		position = 3,
		section = SECTION_POINTS_TRACKER
	)
	default boolean pointsTrackerShowTeamUniqueChance()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pointsTrackerShowPersonalUniqueChance",
		name = "Show Personal Unique %",
		description = "Show personal unique chance on the overlay.",
		position = 4,
		section = SECTION_POINTS_TRACKER
	)
	default boolean pointsTrackerShowPersonalUniqueChance()
	{
		return false;
	}

	@ConfigItem(
		keyName = "pointsTrackerPostRaidMessage",
		name = "Points Total Message",
		description = "Show the total points in chat after the raid, akin to the Chambers of Xeric.",
		position = 6,
		section = SECTION_POINTS_TRACKER
	)
	default boolean pointsTrackerPostRaidMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pointsTrackerAllowExternal",
		name = "Send to External Plugins",
		description = "Sends the points totals to other locally installed plugins on raid completion." +
			"<br />Disabling this may prevent other plugins from working properly.",
		position = 7,
		section = SECTION_POINTS_TRACKER
	)
	default boolean pointsTrackerAllowExternal()
	{
		return true;
	}

	// hidden

	@ConfigItem(
		keyName = "updateNotifierLastVersion",
		name = "",
		description = "",
		hidden = true
	)
	default int updateNotifierLastVersion()
	{
		return UpdateNotifier.TARGET_VERSION - 1;
	}

	@ConfigItem(
		keyName = "updateNotifierLastVersion",
		name = "",
		description = "",
		hidden = true
	)
	void updateNotifierLastVersion(int newVersion);
}

package com.duckblade.osrs.tfa;

import com.duckblade.osrs.tfa.module.ComponentManager;
import com.duckblade.osrs.tfa.module.TfaModule;
import com.google.inject.Binder;
import com.google.inject.Inject;
import com.google.inject.Injector;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "The Fractured Archive",
	description = "Utilities and information for raiding The Fractured Archive.",
	tags = {"tfa", "raid", "4"}
)
public class TfaPlugin extends Plugin
{

	public static final String EVENT_NAMESPACE = "the-fractured-archive";

	@Inject
	private Injector injector;

	@Inject
	private ConfigMigrationService configMigrationService;

	private ComponentManager componentManager = null;

	@Override
	public void configure(Binder binder)
	{
		binder.install(new TfaModule());
	}

	@Override
	protected void startUp() throws Exception
	{
		configMigrationService.migrate();

		if (componentManager == null)
		{
			componentManager = injector.getInstance(ComponentManager.class);
		}
		componentManager.onPluginStart();
	}

	@Override
	protected void shutDown() throws Exception
	{
		componentManager.onPluginStop();
	}
}

package com.duckblade.osrs.tfa.features;

import com.duckblade.osrs.tfa.TfaConfig;
import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
import com.duckblade.osrs.tfa.util.RaidState;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

@Singleton
public class FadeDisabler
	implements PluginLifecycleComponent
{
	@Inject
	private EventBus eventBus;

	@Override
	public boolean isEnabled(final TfaConfig config, final RaidState raidState)
	{
		return config.hideFadeTransition() && (raidState.isInLobby() || raidState.isInRaid());
	}

	@Override
	public void startUp()
	{
		eventBus.register(this);
	}

	@Override
	public void shutDown()
	{
		eventBus.unregister(this);
	}

	@Subscribe
	private void onScriptPreFired(final ScriptPreFired event)
	{
		// https://github.com/RuneStar/cs2-scripts/blob/master/scripts/%5Bclientscript%2Cfade_overlay%5D.cs2
		if (event.getScriptId() == 948)
		{
			event.getScriptEvent().getArguments()[4] = 255; // transparency (default=0)
			event.getScriptEvent().getArguments()[5] = 0; // duration? (default=50)
		}
	}
}

package com.duckblade.osrs.tfa.features;

import com.duckblade.osrs.tfa.TfaConfig;
import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
import com.duckblade.osrs.tfa.util.RaidState;
import javax.inject.Inject;
import javax.inject.Singleton;
import joptsimple.internal.Strings;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class LobbyBoardHighlighter
	implements PluginLifecycleComponent
{

	private static final int SCRIPT_ID_TFA_PARTYDETAILS_ADDMEMBER = 10053;
	private static final int SCRIPT_ID_TFA_PARTYLIST_ADDLINE = 10094;

	private final Client client;

	private boolean needScanPartyMembers;
	private boolean needScanPartyList;

	@Override
	public boolean isEnabled(TfaConfig config, RaidState raidState)
	{
		return config.lobbyBoardFriendHighlighter();
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired e)
	{
		if (e.getScriptId() == SCRIPT_ID_TFA_PARTYDETAILS_ADDMEMBER)
		{
			needScanPartyMembers = true;
		}
		else if (e.getScriptId() == SCRIPT_ID_TFA_PARTYLIST_ADDLINE)
		{
			needScanPartyList = true;
		}
	}

	@Subscribe
	public void onClientTick(ClientTick e)
	{
		if (needScanPartyMembers)
		{
			scanPartyMembers();
			needScanPartyMembers = false;
		}

		if (needScanPartyList)
		{
			scanPartyList();
			needScanPartyList = false;
		}
	}

	private void scanPartyMembers()
	{
		log.trace("tfa addmember");
		Widget memberList = client.getWidget(InterfaceID.TfaPartydetails.MEMBERS_LIST);
		if (memberList == null)
		{
			return;
		}

		for (int i = 0; i < 8; i++)
		{
			// 13 elts per row, name is second in each row
			replaceName(memberList.getChild((14 * i) + 1));
		}
	}

	private void scanPartyList()
	{
		log.trace("tfa addline");
		Widget partyList = client.getWidget(InterfaceID.TfaPartylist.LIST);
		Widget[] staticChildren;
		if (partyList == null || (staticChildren = partyList.getStaticChildren()) == null)
		{
			return;
		}

		for (Widget w : staticChildren)
		{
			replaceName(w.getChild(2));
		}
	}

	private void replaceName(Widget memberName)
	{
		if (memberName == null || Strings.isNullOrEmpty(memberName.getText()))
		{
			return;
		}

		String member = Text.removeTags(memberName.getText());
		if (isFriend(member))
		{
			memberName.setText("<img=32> " + member);
			memberName.setTextColor(0x00ff00);
		}
		else if (isIgnored(member))
		{
			memberName.setText("<img=11> " + member);
			memberName.setTextColor(0xff0000);
		}
	}

	private boolean isFriend(String name)
	{
		return !Strings.isNullOrEmpty(name) &&
			client.getFriendContainer().findByName(Text.removeTags(name)) != null;
	}

	private boolean isIgnored(String name)
	{
		return !Strings.isNullOrEmpty(name) &&
			client.getIgnoreContainer().findByName(Text.removeTags(name)) != null;
	}
}

