package com.duckblade.osrs.tfa.features.updatenotifier;

import com.duckblade.osrs.tfa.TfaConfig;
import com.duckblade.osrs.tfa.module.PluginLifecycleComponent;
import com.duckblade.osrs.tfa.util.RaidState;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.RequiredArgsConstructor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class UpdateNotifier
	implements PluginLifecycleComponent
{

	public static final int TARGET_VERSION = 5;
	private static final BufferedImage PANEL_ICON = ImageUtil.loadImageResource(UpdateNotifier.class, "icon.png");

	private final ClientToolbar clientToolbar;
	private final TfaConfig config;

	private NavigationButton navButton;

	@Override
	public boolean isEnabled(TfaConfig config, RaidState raidState)
	{
		return config.showUpdateMessages() &&
			config.updateNotifierLastVersion() < TARGET_VERSION &&
			raidState.isInLobby();
	}

	@Override
	public void startUp()
	{
		SwingUtilities.invokeLater(() ->
		{
			navButton = NavigationButton.builder()
				.tooltip("TFA Plugin Updates")
				.priority(999)
				.icon(PANEL_ICON)
				.panel(new UpdateNotifierPanel(getUpdates(), () ->
				{
					config.updateNotifierLastVersion(TARGET_VERSION);
					clientToolbar.removeNavigation(navButton);
				}))
				.build();

			clientToolbar.addNavigation(navButton);

			SwingUtilities.invokeLater(() -> clientToolbar.openPanel(navButton));
		});
	}

	@Override
	public void shutDown()
	{
		SwingUtilities.invokeLater(() -> clientToolbar.removeNavigation(navButton));
	}

	private List<String> getUpdates()
	{
		List<String> updates = new ArrayList<>();

		switch (config.updateNotifierLastVersion())
		{
			case 0:
				updates.add("<strong>(Miscellaneous -> Lobby Board Highlight) Highlights friends' and ignores' names on the party lobby board.");
				updates.add("<strong>(Miscellaneous -> HP Orbs) Hide HP Orbs, or replace them with health bars.");
				updates.add("<strong>(Miscellaneous -> Hide Fade Transition) Hides the screen fade-to-black between rooms.");

			case 1:
				updates.add("<strong>(Loot -> Bank-all Single Click) Left-click only for Bank-all on the loot interface.");
				updates.add("<strong>(Loot -> Prevent Early Sparkle) Hides the loot chest sparkling until you would have triggered the purple chest animation.");

			case 2:
				updates.add("<strong>(Points Tracker) Added a points tracker showing team and personal purple rates. Unlike the ToA points tracker, this one only updates at the end of rooms, and does not require the party plugin.");
				updates.add("<strong>(Removed Loot -> Prevent Early Sparkle) Jagex has implemented this themselves.");

			case 3:
				updates.add("<string>(Loot -> Loot Chest Highlight) Added a chest highlight to help quickly identify your loot chest.");
				updates.add("<string>(Lobby -> Loot Reminder) A reminder to claim your loot if you did not claim it in the raid.");
				updates.add("<string>(Lobby -> Spellbook Warning) Displays your current spellbook on the raid entrance.");

			case 4:
				updates.add("<string>Points Tracker</strong> Now uses the RL Party system to get more accurate counts. <em>ALL</em> players must be in party with the TFA plugin or else you will get very inaccurate estimates.");
		}

		return updates;
	}
}

package com.duckblade.osrs.tfa.features.updatenotifier;

import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.PluginPanel;

public class UpdateNotifierPanel extends PluginPanel
{

	UpdateNotifierPanel(List<String> updates, Runnable acknowledgeCallback)
	{
		super(true);

		setBorder(BorderFactory.createEmptyBorder(20, 5, 0, 5));
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));

		JLabel content = new JLabel();
		content.setText(buildHtml(updates));
		content.setHorizontalAlignment(SwingConstants.CENTER);
		content.setAlignmentX(CENTER_ALIGNMENT);
		content.setBorder(BorderFactory.createEmptyBorder(0, 0, 20, 0));
		add(content);

		JButton acknowledge = new JButton("Close");
		acknowledge.addActionListener(ignored -> acknowledgeCallback.run());
		acknowledge.setAlignmentX(CENTER_ALIGNMENT);
		add(acknowledge);
	}

	private static String buildHtml(List<String> updates)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("<html>");

		sb.append("<h1 style=\"width: 1%; margin: 0 auto;\">TFA\u00A0Plugin\u00A0Updates</h1>");
		sb.append("<br/><br/>");

		sb.append("<em>While the raid is new, features are going to be limited to give people time to experience the raid as designed. Please be patient!</em>");
		sb.append("<br/><br/>");

		sb.append("<ul style=\"list-style-type: disc; margin: 0px 15px;\">");
		for (String update : updates)
		{
			sb.append("<li>");
			sb.append(update);
			sb.append("</li>");
			sb.append("<br/>");
		}
		sb.append("</ul><br/>");

		sb.append("<em>With all updates, please check the plugin config to enable or disable features you wish to use.</em>");

		sb.append("</html>");
		return sb.toString();
	}
}

package com.duckblade.osrs.tfa.module;

import com.duckblade.osrs.tfa.TfaConfig;
import com.duckblade.osrs.tfa.util.RaidState;
import com.duckblade.osrs.tfa.util.RaidStateChanged;
import com.duckblade.osrs.tfa.util.RaidStateTracker;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.GameEventManager;

/**
 * Manages all the subcomponents of the plugin
 * so they can register themselves to RuneLite resources
 * e.g. EventBus/OverlayManager/init on startup/etc
 * instead of the TheFracturedArchivePlugin class handling everything.
 */
@Singleton
@RequiredArgsConstructor(onConstructor = @__(@Inject))
@Slf4j
public class ComponentManager
{

	private final EventBus eventBus;
	private final OverlayManager overlayManager;
	private final GameEventManager gameEventManager;
	private final TfaConfig config;
	private final RaidStateTracker raidStateTracker;
	private final Set<PluginLifecycleComponent> components;

	private final Map<PluginLifecycleComponent, Boolean> states = new HashMap<>();

	public void onPluginStart()
	{
		eventBus.register(this);
		components.forEach(c -> states.put(c, false));
		revalidateComponentStates();
	}

	public void onPluginStop()
	{
		eventBus.unregister(this);
		components.stream()
			.filter(states::get)
			.forEach(this::tryShutDown);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!TfaConfig.CONFIG_GROUP.equals(e.getGroup()))
		{
			return;
		}

		revalidateComponentStates();
	}

	@Subscribe
	public void onRaidStateChanged(RaidStateChanged e)
	{
		revalidateComponentStates();
	}

	private void revalidateComponentStates()
	{
		RaidState raidState = raidStateTracker.getCurrentState();
		components.forEach(c ->
		{
			boolean shouldBeEnabled = c.isEnabled(config, raidState);
			boolean isEnabled = states.get(c);
			if (shouldBeEnabled == isEnabled)
			{
				return;
			}

			if (shouldBeEnabled)
			{
				tryStartUp(c);
			}
			else
			{
				tryShutDown(c);
			}
		});
	}

	private void tryStartUp(PluginLifecycleComponent component)
	{
		if (states.get(component))
		{
			return;
		}

		if (log.isDebugEnabled())
		{
			log.debug("Enabling TFA plugin component [{}]", component.getClass().getName());
		}

		try
		{
			eventBus.register(component);
			if (component instanceof Overlay)
			{
				overlayManager.add((Overlay) component);
			}

			component.startUp();
			gameEventManager.simulateGameEvents(component);
			states.put(component, true);
		}
		catch (Throwable e)
		{
			log.error("Failed to start TFA plugin component [{}]", component.getClass().getName(), e);
		}
	}

	private void tryShutDown(PluginLifecycleComponent component)
	{
		if (!states.get(component))
		{
			return;
		}

		if (log.isDebugEnabled())
		{
			log.debug("Disabling TFA plugin component [{}]", component.getClass().getName());
		}

		try
		{
			component.shutDown();
		}
		catch (Throwable e)
		{
			log.error("Failed to cleanly shut down TFA plugin component [{}]", component.getClass().getName());
		}
		finally
		{
			states.put(component, false);
		}

		eventBus.unregister(component);
		if (component instanceof Overlay)
		{
			overlayManager.remove((Overlay) component);
		}
	}

}

