package com.duckblade.osrs.tfa.launcher.debugplugins;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.LoggerContext;
import ch.qos.logback.classic.encoder.PatternLayoutEncoder;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.FileAppender;
import java.io.File;
import java.text.SimpleDateFormat;
import java.util.Date;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import org.slf4j.LoggerFactory;

/**
 * Dev-build only. Attaches a dedicated logback file appender to the whole
 * {@code com.duckblade.osrs.tfa} package at TRACE, capturing every hitsplat, chat message, party
 * message and points ledger adjustment the plugin logs (see the log statements throughout that
 * package) to a single timestamped file - a complete, out-of-band-analyzable record of a raid,
 * meant to be collected from testers. Expect these files to be large; that's intentional.
 * <p>
 * Only {@link TfaDebugPlugin} uses this - it is not wired into the shipped plugin in any way.
 */
@Slf4j
@Singleton
public class EventFileLogger
{

	private static final String TARGET_LOGGER_NAME = "com.duckblade.osrs.tfa";

	private FileAppender<ILoggingEvent> appender;
	private Level previousLevel;

	public void start()
	{
		LoggerContext context = (LoggerContext) LoggerFactory.getILoggerFactory();
		Logger target = context.getLogger(TARGET_LOGGER_NAME);

		File dir = new File(RuneLite.LOGS_DIR, "tfa-points-debug");
		dir.mkdirs();
		String fileName = "tfa-points-" + new SimpleDateFormat("yyyyMMdd-HHmmss").format(new Date()) + ".log";
		File file = new File(dir, fileName);

		PatternLayoutEncoder encoder = new PatternLayoutEncoder();
		encoder.setContext(context);
		encoder.setPattern("%d{ISO8601} [%thread] %-5level %logger{36} - %msg%n");
		encoder.start();

		FileAppender<ILoggingEvent> fileAppender = new FileAppender<>();
		fileAppender.setContext(context);
		fileAppender.setName("TFA_EVENT_LOG");
		fileAppender.setFile(file.getAbsolutePath());
		fileAppender.setImmediateFlush(true);
		fileAppender.setEncoder(encoder);
		fileAppender.start();

		previousLevel = target.getLevel();
		target.setLevel(Level.TRACE);
		target.addAppender(fileAppender);

		appender = fileAppender;

		log.info("TFA event log started: {}", file.getAbsolutePath());
	}

	public void stop()
	{
		if (appender == null)
		{
			return;
		}

		LoggerContext context = (LoggerContext) LoggerFactory.getILoggerFactory();
		Logger target = context.getLogger(TARGET_LOGGER_NAME);
		target.detachAppender(appender);
		target.setLevel(previousLevel);

		appender.stop();
		appender = null;
	}

}

package com.duckblade.osrs.tfa.launcher.debugplugins;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class MenuEntryDumper
{

	private final TfaDebugConfig config;

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded e)
	{
		if (!config.menuEntryDumper())
		{
			return;
		}

		if (e.getOption().equals("Walk here") ||
			e.getOption().equals("Cancel"))
		{
			return;
		}

		log.debug(
			"{} | '{}' on '{}' ({}, {})",
			e.getMenuEntry().getType(),
			e.getOption(),
			e.getTarget(),
			e.getActionParam0(),
			e.getActionParam1()
		);
	}

}

package com.duckblade.osrs.tfa.launcher.debugplugins;

import com.duckblade.osrs.tfa.util.RaidCompletionTracker;
import com.duckblade.osrs.tfa.util.RaidStateTracker;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class StateOverlay extends OverlayPanel
{

	public enum StateDisplays
	{
		PATH_LEVELS,
		RAID_STATE,
		ROOM_COMPLETIONS,
	}

	private final TfaDebugConfig config;

	private final RaidStateTracker raidStateTracker;
	private final RaidCompletionTracker raidCompletionTracker;

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.stateOverlay().isEmpty())
		{
			return null;
		}

		if (config.stateOverlay().contains(StateDisplays.RAID_STATE))
		{
			getPanelComponent().getChildren().addAll(
				List.of(
					TitleComponent.builder()
						.color(Color.ORANGE)
						.text("Raid State")
						.build(),
					LineComponent.builder()
						.left("In Raid")
						.rightColor(raidStateTracker.getCurrentState().isInRaid() ? Color.GREEN : Color.RED)
						.right(String.valueOf(raidStateTracker.getCurrentState().isInRaid()))
						.build(),
					LineComponent.builder()
						.left("In Lobby")
						.rightColor(raidStateTracker.getCurrentState().isInLobby() ? Color.GREEN : Color.RED)
						.right(String.valueOf(raidStateTracker.getCurrentState().isInLobby()))
						.build(),
					LineComponent.builder()
						.left("Room")
						.right(String.valueOf(raidStateTracker.getCurrentState().getCurrentRoom()))
						.build(),
					LineComponent.builder()
						.left("Players")
						.right(String.valueOf(raidStateTracker.getCurrentState().getPlayerCount()))
						.build()
				)
			);
		}

		if (config.stateOverlay().contains(StateDisplays.ROOM_COMPLETIONS))
		{
			getPanelComponent().getChildren().add(
				TitleComponent.builder()
					.color(Color.ORANGE)
					.text("Completion")
					.build()
			);
			for (String boss : raidCompletionTracker.getCompletedBosses())
			{
				getPanelComponent().getChildren().add(
					LineComponent.builder()
						.right(boss)
						.build()
				);
			}
		}

		return super.render(graphics);
	}
}

